#!/usr/bin/env python3
"""Generate Unicode 15 full case folding for native extraction postprocessing."""
from pathlib import Path
import unicodedata

if unicodedata.unidata_version != "15.0.0":
    raise SystemExit("requires the pinned Python 3.12 / Unicode 15.0.0 oracle")

lines = [
    "// Generated by scripts/gliner25/generate_casefold.py; do not edit.",
    '// Unicode 15.0.0 full default case folding from pinned CPython 3.12.',
    'pub const unicode_version = "15.0.0";',
    "pub const Entry = struct { source: u21, target: [3]u21, len: u2 };",
    "pub const entries = [_]Entry{",
]
for value in range(0x110000):
    source = chr(value)
    folded = source.casefold()
    if source == folded:
        continue
    target = [ord(c) for c in folded]
    assert 1 <= len(target) <= 3
    padded = target + [0] * (3 - len(target))
    lines.append(f"    .{{ .source = 0x{value:x}, .target = .{{ " +
                 ", ".join(f"0x{x:x}" for x in padded) + f" }}, .len = {len(target)} }},")
lines.extend(["};", ""])
output = Path(__file__).resolve().parents[2] / "src/pipelines/extraction_casefold_data.zig"
output.write_text("\n".join(lines))
print(output)
